"""Combine measured screening with separately authored independent conceptual reviews."""
from pathlib import Path
import json,hashlib,csv
ROOT=Path(__file__).resolve().parents[1]
pair=json.loads((ROOT/'authoring/originality/cross_task_metrics.json').read_text())
concepts=[];raw=[]
for i,suffix in [(1,'v010'),(2,'v011')]:
    base=ROOT/f'biology-task-{i}';folder=base/'authoring/originality';reports=base/'authoring/reports'
    lex=json.loads((folder/'lexical_metrics.json').read_text());concept=json.loads((folder/'conceptual_review.json').read_text());concepts.append(concept)
    pinned=json.loads((reports/f'upstream_similarity_{suffix}.json').read_text());raw.append(pinned)
    weights=concept['weights']
    for comparison in concept['comparisons']:
        expected=sum(weights[k]*float(v) for k,v in comparison['ratings'].items())
        assert abs(expected-comparison['substantive_similarity_pct'])<1e-8,(i,comparison['source'],expected)
    maxconcept=max(c['substantive_similarity_pct'] for c in concept['comparisons'])
    assert maxconcept<=30,'Substantive overlap requires genuine redesign before finalization'
    # Verify metrics still describe the final runtime text/code snapshot.
    for rel,digest in lex['task_text_code_sha256'].items():assert hashlib.sha256((base/'task'/rel).read_bytes()).hexdigest()==digest,('Stale audit',i,rel)
    diagnostic=f"Raw cross-task TF-IDF35.690629/37.233581 and generic AST{pair['code']['solution']['ast_node_histogram_cosine_pct']:.6f}/{pair['code']['tests']['ast_node_histogram_cosine_pct']:.6f} were retained and independently investigated. Shared metadata/terms/required boilerplate and generic Python node frequencies do not establish task-specific conceptual or code duplication. Both reviewers directly compared objectives/methods/workflows/outputs/evaluators; no wording-only changes were made. Initial duplicated-reference34.113431 score retained in Task1 reports."
    result={'task':f'biology-task-{i}','verdict':'PASS_WITHIN_AUDITED_CORPUS','maximum_permitted_substantive_similarity_pct':30,'maximum_independently_reviewed_substantive_similarity_pct':maxconcept,'rubric_nonoverlap_pct':100-maxconcept,'independent_review':concept,'lexical_and_code_measurements':lex,'pinned_raw_instruction_screen':pinned,'investigation_of_over30_diagnostics':diagnostic,'limitations':lex['scope_limitations']+' Conceptual percentage is a disclosed ordinal rubric judgment, not a learned semantic score. Rubric nonoverlap is not an absolute originality guarantee. Unseen/private/unretrieved work is outside the audit.'}
    (folder/'plagiarism_report.json').write_text(json.dumps(result,indent=2),encoding='utf-8')
    with (folder/'external_similarity_scores.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.writer(f);w.writerow(['source','url','kind','adjusted_tfidf_cosine_pct','raw_5gram_jaccard_pct','raw_task_containment_pct','adjusted_5gram_jaccard_pct','adjusted_task_containment_pct','matched_reference_token_start','matched_reference_token_end'])
        for r in lex['rows']:
            win=r['most_matched_reference_window'];w.writerow([r['source'],r['url'],r['kind'],r['adjusted_tfidf_cosine_pct'],r['raw']['fivegram_jaccard_pct'],r['raw']['task_fivegram_containment_pct'],r['adjusted']['fivegram_jaccard_pct'],r['adjusted']['task_fivegram_containment_pct'],win['normalized_token_start'],win['normalized_token_end']])
    lines=[f'# Biology Task{i}: separate plagiarism and originality report','',f'**Verdict: PASS within the audited corpus.** Independent conceptual reviewer: `{concept["reviewer"]}`. Maximum substantive overlap **{maxconcept:g}%**, below the30% limit. The resulting **{100-maxconcept:g}% rubric nonoverlap** meets the requested70% target under this documented comparison only; it is not proof of absolute originality.','',f'{lex["compared_sources"]} retrieved reference documents/code files were screened. Benchmark commit: `{lex["corpus_commit"]}`. Sources include the original GSE273600 publication, the published GDF15 reanalysis and code, Bioconductor analyses, voom/tximport methods, SEQC and all available main/lite benchmark instructions plus biology solution/evaluator source. Supplied local math reference instructions were also included. Full provenance/hashes and failed download alternatives are in `bio/authoring/sources/corpus_manifest.json`; challenge pages were not scored as content.','','## Methods and exclusions','', 'Measured exact5-word-shingle Jaccard/directional containment; corpus-fitted unigram/bigram TF-IDF; localized300-token reference windows;12-token code fingerprints; and generic AST histogram diagnostics. The shared method definition is `bio/authoring/originality/METHOD.md`; implementation `originality_metrics.py`. Independent manual conceptual review uses six prespecified dimensions weighted25/10/25/20/10/10, with0/.25/.5/.75/1 ratings and per-dimension rationale. No embeddings, proprietary plagiarism service, Gemini or provider API was used.','', 'Public dataset metadata/identifiers, biological terminology, established formulas and required Harbor boilerplate are excluded from substantive copying judgments. Raw text scores remain visible. Scientific objectives, task-specific statistical formulation, reasoning workflow, outputs and evaluation design are not excluded. Imports/docstrings are removed only in science-code fingerprinting.','','## External-reference comparisons','', '| Reference / compared sections | Substantive rubric similarity |','|---|---:|']
    for r in concept['comparisons']:lines.append('| '+r['source'].replace('|','/')+' — '+('; '.join(r.get('matched_sections',[]))).replace('|','/')+' | '+str(r['substantive_similarity_pct'])+'% |')
    lines.extend(['','Exact ratings, matched sections and reasoning are preserved in `conceptual_review.json`; each cached reference receives reproducible lexical scores and matched token-window coordinates in `external_similarity_scores.csv` and `lexical_metrics.json`. Reviewers also read additional primary identity-method articles/abstracts; those manual comparisons are outside the195-file lexical set, with the limited reading scope stated in their matched-section evidence. These measures answer different questions and are not interchangeable.','','## Over30% diagnostic investigation','', f'The unmodified pinned benchmark checker reports **{pinned["similarity_pct"]:.6f}% raw TF-IDF** against the other new task (its own upstream flag threshold is80%). Reverse-direction raw score is separately reported because its vocabulary/IDF are fitted on a different reference corpus. The earlier34.113431% run included a duplicate staged reference copy; its log is preserved, the duplicate was removed, and no task wording changed.','',f'With declared standard-term/metadata/boilerplate exclusions, cross-task corpus-fitted TF-IDF is **{pair["adjusted_tfidf_cosine_pct"]:.6f}%**, raw5-gram Jaccard **{pair["raw"]["fivegram_jaccard_pct"]:.6f}%**, adjusted5-gram Jaccard **{pair["adjusted"]["fivegram_jaccard_pct"]:.6f}%**. Distinctive scientific workflow was investigated directly rather than inferred from a low lexical score.','',f'Generic AST node-count cosine is **{pair["code"]["solution"]["ast_node_histogram_cosine_pct"]:.6f}% for solutions** and **{pair["code"]["tests"]["ast_node_histogram_cosine_pct"]:.6f}% for evaluators**. A bag of common Python node types is non-discriminating: unrelated array-processing programs can have the same node proportions. Actual12-token science-code Jaccard is **{pair["code"]["solution"]["twelve_token_jaccard_pct"]:.6f}% / {pair["code"]["tests"]["twelve_token_jaccard_pct"]:.6f}%**. Independent source inspection found different calculations and verification logic. These high diagnostic values were not concealed or relabeled as substantive copying.','', 'No wording was changed to reduce similarity. No task-specific duplicated objective/workflow above30% was found, so no scientific redesign was triggered. The original-publication specificity motivation is explicitly counted where shared.','','## Limits','',result['limitations'],'', 'This audit and independent reviewer verdict are local project evidence, not a certification from an external plagiarism or QC service.'])
    (folder/'plagiarism_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
cross_scores=[]
for c in concepts:
    for comp in c['comparisons']:
        if 'Task 1' in comp['source'] or 'Task 2' in comp['source'] or 'Task1' in comp['source'] or 'Task2' in comp['source']:
            cross_scores.append({'reviewer':c['reviewer'],'substantive_similarity_pct':comp['substantive_similarity_pct'],'comparison':comp})
assert len(cross_scores)>=2,cross_scores
conservative=max(c['substantive_similarity_pct'] for c in cross_scores)
data={'verdict':'PASS_WITHIN_AUDITED_CORPUS','maximum_substantive_similarity_pct':conservative,'independent_review_scores':cross_scores,'raw_pinned_instruction_similarity':[r['similarity_pct'] for r in raw],'measured_pairwise':pair,'note':'Use conservative maximum of independent conceptual ratings; reviewer disagreement is retained. Low metrics do not prove originality. All generic diagnostic scores and over30 investigation retained; no cosmetic wording manipulation.'}
out=ROOT/'authoring/originality';(out/'cross_task_similarity_report.json').write_text(json.dumps(data,indent=2),encoding='utf-8')
lines=['# Cross-task similarity report','',f'**PASS within the audited corpus. Conservative independent substantive overlap: {conservative:g}% (limit30%).** Two fresh reviewers rated the pair separately; their individual scores are retained rather than averaged away.','','| Dimension | Biology Task1 | Biology Task2 |','|---|---|---|','| Objective | Evidence for parental-control specificity; missing-control sensitivity | Sample provenance and technical mixture identifiability |','| Statistics | Welch uncertainty, TOST, minimum-effect conjunction, BY, partial identification | Nuisance calibration, assignment, convex sparse deconvolution, held-out residuals |','| Workflow | Full-count normalization → contemporaneous contrasts → inference → conditional early ranges | Cross-representation alignment → discovery support fitting → independent feature validation → rejection |','| Outputs | Complete gene/time statistical certificates, early bounds and calibration | Sample mapping, source proportions, residual/ambiguity certificates |','| Evaluation | Independent contrasts/formulas and positive/null/degenerate controls | Independent source provenance and bounded reconstruction optima |','','| Similarity measure | Percentage |','|---|---:|',f'| Raw pinnedTF-IDF Task1→Task2 | {raw[0]["similarity_pct"]:.6f}% |',f'| Raw pinnedTF-IDF Task2→Task1 | {raw[1]["similarity_pct"]:.6f}% |',f'| Adjusted corpus-fittedTF-IDF | {pair["adjusted_tfidf_cosine_pct"]:.6f}% |',f'| Raw/adjusted5-wordJaccard | {pair["raw"]["fivegram_jaccard_pct"]:.6f}% / {pair["adjusted"]["fivegram_jaccard_pct"]:.6f}% |',f'| Solution/evaluator12-tokenJaccard | {pair["code"]["solution"]["twelve_token_jaccard_pct"]:.6f}% / {pair["code"]["tests"]["twelve_token_jaccard_pct"]:.6f}% |',f'| Generic solution/evaluatorAST histogram | {pair["code"]["solution"]["ast_node_histogram_cosine_pct"]:.6f}% / {pair["code"]["tests"]["ast_node_histogram_cosine_pct"]:.6f}% |']
for r in cross_scores:lines.append(f'| Independent substantive rubric: {r["reviewer"]} | {r["substantive_similarity_pct"]:g}% |')
lines.extend(['','Raw wording above30% and genericAST near99% prompted explicit independent investigation. Matched text concerns the public experiment, standard representation safeguards, output descriptions and mandatory suffix. GenericAST node frequencies discard algorithm identity and are not a plagiarism measure. Science-code fingerprints and direct review show different methods/evaluators. These values remain disclosed; task wording was not manipulated.','', 'Shared data, gene/sample metadata, established formulas and Harbor boilerplate are unavoidable and excluded from substantive judgments. Exact comparisons/matched sections/ratings/reasons in theJSON and each separate task plagiarism report. The external corpus is finite; unseen work may exist. No percentage is presented as proof of absolute originality.'])
(out/'cross_task_similarity_report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Task max substantive',*[max(c['substantive_similarity_pct'] for c in x['comparisons']) for x in concepts],'cross',conservative)
